import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
import { useDisplay } from "vuetify/lib/framework.mjs";
import LoggedForm from "@/components/VisitsManagementApp/AdminApp/AdminDialogues/LoggedForm.vue";
import LogLocation from "@/components/VisitsManagementApp/AdminApp/AdminDialogues/LogLocation.vue";
import { formatedatetime } from "@/JsonFiles/DateFormate.js";
import { list_all_user_visit_logs } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_visittype_master } from "@/mixins/GetVisitMaster";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
export default {
  mixins: [get_all_org_users, get_visittype_master],
  components: {
    LogLocation,
    LoggedForm
  },
  data() {
    return {
      fixed: true,
      locationlogged: false,
      searchF: "",
      goLoading: false,
      clearData: false,
      userselect: "ALL",
      userArray: [],
      visitArray: [],
      searchvisit: "",
      visitselect: "ALL",
      monthPicker: false,
      datedisplay: "",
      datedisplayMonth: "",
      yearfilter: new Date().getFullYear(),
      monthfilter: "",
      monthNames: ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],
      itemyears: [],
      componentCheck: 0,
      height: 0,
      formlog: false,
      rowInfo: {},
      CommonVuetifyObj: {},
      tableData: [],
      tableLoading: false,
      headers: [{
        title: "Visited On",
        key: "log_initiated_on",
        sortable: false
      }, {
        title: "Visited By",
        key: "log_initiated_by",
        sortable: false
      }, {
        title: "Type Of Visit",
        key: "visit_type_id_text",
        sortable: false
      }, {
        title: "Location",
        key: "visit_loc",
        sortable: false
      }, {
        title: "Visit Details",
        key: "actions",
        sortable: false
      }],
      itemsPerPage: 20,
      currentPage: 1,
      totalItems: 0,
      search: ""
    };
  },
  computed: {
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.tableData.slice(start, end);
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  watch: {
    date(val) {
      this.date1 = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"][Number(val.split("-")[1]) - 1] + " " + val.split("-")[0];
    },
    tableData() {
      this.totalItems = this.tableData.length;
    },
    currentPage(newVal) {
      // Optional: scroll to top of table on page change
      const table = document.querySelector(".dtwidth");
      if (table) table.scrollIntoView({
        behavior: "smooth",
        block: "start"
      });
    }
  },
  async mounted() {
    this.CommonVuetifyObj = useDisplay();
    await Promise.all([this.fetch_visit(), this.get_all_org_users(), this.get_visittype_master()]);
    await this.fetch_details();
    this.populateYearItems();
    this.setInitialFilters();
  },
  methods: {
    fetch_details() {
      // Clear arrays before populating
      this.userArray = [];
      this.visitArray = [];
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE") {
          this.userArray.push({
            full_user_name: element.full_user_name,
            user_id: element.user_email_id
          });
        }
      });
      // Add 'All' only once at the start
      this.userArray.unshift({
        full_user_name: "All",
        user_id: "ALL"
      });
      this.Mastervisit.forEach(element => {
        this.visitArray.push({
          full_user_name: element.workflow_name + " V " + element.workflow_version,
          user_id: element.workflow_id
        });
      });
      // Add 'All' only once at the start
      this.visitArray.unshift({
        full_user_name: "All",
        user_id: "ALL"
      });
    },
    async get_data() {
      this.goLoading = true;
      this.tableData = [];
      this.fetch_visit();
    },
    async clear_data() {
      this.userselect = "ALL";
      this.visitselect = "ALL";
      this.date = new Date().toISOString().substr(0, 7);
      this.tableData = [];
      this.clearData = true;
      this.fetch_visit();
    },
    fetch_value(date) {
      return formatedatetime(date);
    },
    get_location(item) {
      this.componentCheck = 1;
      this.rowInfo = item;
      this.locationlogged = true;
    },
    viewform(item) {
      this.rowInfo = item;
      this.componentCheck = 2;
      this.formlog = true;
    },
    async fetch_visit() {
      this.tableLoading = true;
      try {
        let result = await API.graphql(graphqlOperation(list_all_user_visit_logs, {
          input: {
            nextToken: null,
            limit: 100,
            workflow_id: this.visitselect,
            month_year: this.date,
            user_email_id: this.userselect
          }
        }));
        this.tableLoading = false;
        this.goLoading = false;
        this.clearData = false;
        var response = JSON.parse(result.data.list_all_user_visit_logs);
        if (response.Status == "SUCCESS") {
          this.tableLoading = false;
          this.goLoading = false;
          this.clearData = false;
          this.tableData = response.data;
        } else {
          this.tableLoading = false;
          this.goLoading = false;
          this.clearData = false;
          this.tableData = [];
        }
      } catch (error) {
        this.goLoading = false;
        this.clearData = false;
        this.tableLoading = false;
        this.tableData = [];
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    populateYearItems() {
      const currentYear = new Date().getFullYear();
      this.itemyears = Array.from({
        length: 10
      }, (_, index) => currentYear - index);
    },
    setInitialFilters() {
      const currentYear = new Date().getFullYear();
      this.yearfilter = currentYear;
      this.monthfilter = this.monthNames[new Date().getMonth()] || "Jan";
      this.updateDatedisplayMonth();
      this.datedisplay = this.datedisplayMonth || `${this.monthfilter} ${this.yearfilter}`;
    },
    updateDatedisplayMonth() {
      if (this.yearfilter && this.monthfilter) {
        this.datedisplayMonth = `${this.monthfilter} ${this.yearfilter}`;
      } else {
        const currentDate = new Date();
        this.datedisplayMonth = `${this.monthNames[currentDate.getMonth()]} ${currentDate.getFullYear()}`;
      }
    },
    selectMonth(month) {
      this.monthfilter = month;
    },
    closedialog() {
      this.monthPicker = false;
    },
    saveSelection() {
      this.datedisplay = this.monthfilter + " " + this.yearfilter;
      this.monthPicker = false;
      this.get_data();
    },
    isMonthDisabled(index) {
      const currentYear = new Date().getFullYear();
      const currentMonth = new Date().getMonth();
      if (this.yearfilter === currentYear && index > currentMonth) {
        return true;
      }
      return false;
    }
  }
};
